    "conn_frontend",
    "conn_server",
    "docker_stream",
    "docker_time",
    "envelope",
    "error_message",
    "frontend",
    "frontend_ssl",
    "haproxy_accept_date",
    "http_host",
    "http_method",
    "http_path",
    "http_protocol",
    "http_query",
    "http_request",
    "http_uri",
    "log_level",
    "log_type",
    "queue_backend",
